        prompt: "Which languages are often used for data analysis or database work?",
        choices: ["Python", "R", "SQL", "Assembly"]
      }
    ];

    function Choice({ questionId, value }) {
      const id = `${questionId}-${value.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

      return `
        <label class="choice" for="${id}">
          <input type="checkbox" id="${id}" name="${questionId}" value="${value}">
          <span class="choice-text">${value}</span>
        </label>
      `;
