     function Choice({ questionId, value }) {
       const id = `${questionId}-${value.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

       return `
         <label class="choice" for="${id}">
           <input type="checkbox" id="${id}" name="${questionId}" value="${value}">
           <span class="choice-text">${value}</span>
         </label>
       `;
     }

     function QuestionField({ id, prompt, helpText, choices }, index) {
       const helpId = helpText ? `${id}-help` : "";
       const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

       return `
         <div class="form-field">
           <fieldset${describedBy}>
             <legend>${index + 1}. ${prompt}</legend>
             ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
             <div class="choices">
               ${choices.map((choice) => Choice({ questionId: id, value: choice })).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function QuizApp({ questions }) {
       return questions.map((question, index) => QuestionField(question, index)).join("");
